POST /collections/docs/points/query
{
    "prefetch": {
        "prefetch": [
            {
                "query": {
                    "indices": [1, 42],    // note
                    "values": [0.22, 0.8]  // note
                },
                "using": "sparse",
                "limit": 100
            },
            {
                "query": [0.01, 0.45, 0.67, ...], // note
                "using": "dense",
                "limit": 100
            }
        ],
        "query": { "rrf": {} },
        "limit": 100
    },
    "query": {
        "formula": {
            "sum": [
                "$score", // note
                {
                    "mult": [
                        0.1, // note
                        {
                            "exp_decay": {
                                "x": {
                                    "datetime_key": "published_at"
                                },
                                "target": {
                                    "datetime": "YYYY-MM-DDT00:00:00Z"
                                },
                                "scale": 15552000, // note
                                "midpoint": 0.5
                            }
                        }
                    ]
                }
            ]
        }
    },
    "limit": 10
}

